<template><div class="blog-page" dir="rtl"><section class="blog-hero"><span>مجلهٔ {{ branding.name }}</span><h1>قصه‌ها، طعم‌ها و ایده‌های تازه</h1><p>از مواد اولیه و روش آماده‌سازی تا پیشنهادهایی برای انتخاب خوش‌طعم بعدی.</p><a href="#blog-list">دیدن مقاله‌ها <ArrowDown :size="17" /></a></section><main id="blog-list" class="blog-main"><div class="blog-filters" v-if="categories.length"><button :class="{active:!selected}" @click="selectCategory('')">همه</button><button v-for="category in categories" :key="category" :class="{active:selected===category}" @click="selectCategory(category)">{{ category }}</button></div><p v-if="loading" class="blog-state">در حال بارگذاری مقاله‌ها...</p><div v-else-if="posts.length" class="blog-grid"><a v-for="post in posts" :key="post.name" :href="`/blog/${encodeURIComponent(post.route)}`" class="blog-card"><img v-if="post.cover_image" :src="post.cover_image" :alt="post.title" loading="lazy"><div v-else class="blog-card__placeholder">{{ branding.name.slice(0,1) }}</div><div class="blog-card__body"><small>{{ post.category || 'مجله' }} <span>·</span> {{ post.read_time }} دقیقه مطالعه</small><h2>{{ post.title }}</h2><p>{{ post.excerpt }}</p><b>خواندن مقاله <ArrowLeft :size="16" /></b></div></a></div><div v-else class="blog-state">هنوز مقاله‌ای در این دسته منتشر نشده است.</div></main></div></template>
<script setup>
import { onMounted, ref } from 'vue'
import { ArrowDown, ArrowLeft } from 'lucide-vue-next'
import { getPublicBlogPosts } from '@/utils/api'
import { resolveBranding } from '@/utils/siteComponents'
const props=defineProps({boot:{type:Object,default:()=>({})}});const branding=resolveBranding(props.boot);const posts=ref([]),categories=ref([]),selected=ref(''),loading=ref(true)
async function load(){loading.value=true;try{const r=await getPublicBlogPosts({limit:48,category:selected.value||undefined});posts.value=r?.posts||[];categories.value=r?.categories||[]}catch{posts.value=[]}finally{loading.value=false}}
function selectCategory(v){selected.value=v;load()}
onMounted(load)
</script>
