ht:900}.blog-card__body{padding:1.1rem}.blog-card small{color:var(--ds-color-action-accent);font-weight:800}.blog-card small span{padding:0 .25rem;color:var(--ds-color-text-muted)}.blog-card h2{margin:.55rem 0;font-size:1.15rem;line-height:1.6}.blog-card p{min-height:3.2em;margin:0 0 .9rem;color:var(--ds-color-text-secondary);line-height:1.8;font-size:.9rem;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.blog-state{padding:3rem 1rem;text-align:center;color:var(--ds-color-text-secondary)}@media(max-width:800px){.blog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.blog-grid{grid-template-columns:1fr}.blog-card img,.blog-card__placeholder{height:200px}}
